import static org.junit.Assert.*;

public class KeyedObjects2D_getObject_TriageGen1Test {

    private KeyedObjects2D keyedObjects2D;
    private final String ROW_KEY_1 = "Row1";
    private final String ROW_KEY_2 = "Row2";
    private final String COL_KEY_1 = "Col1";
    private final String COL_KEY_2 = "Col2";
    private final String TEST_VALUE = "TestData";

    @Before
    public void setUp() {
        keyedObjects2D = new KeyedObjects2D();
    }

    @Test
    public void testGetObject_NullRowKey_ThrowsIllegalArgumentException() {
        try {
            keyedObjects2D.getObject(null, COL_KEY_1);
            fail("Expected IllegalArgumentException for null rowKey");
        } catch (IllegalArgumentException e) {
            assertEquals("Null 'rowKey' argument.", e.getMessage());
        }
    }












}

