    @Before
    public void setUp() {
        keyedObjects2D = new KeyedObjects2D();
    }













    @Test
    public void testGetObject_MultipleEntries() {
        keyedObjects2D.addObject("Val1", ROW_KEY_1, COL_KEY_1);
